class AppError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = "AppError";
  }
}

class DbError extends AppError {}

const low = new RangeError("pool is full");
const error = new DbError("query failed", { cause: low });

console.log(error.name);
console.log(error instanceof AppError, error instanceof RangeError);
console.log(error.cause instanceof RangeError);
console.log(String(error));
